H('247.d.3.H',3,"In a decentralized organization, decisions are made:","By lower-level managers close to the work",["Only by top executives","By no one","By customers only"],"Authority is spread out.")
H('247.d.3.H',4,"A centralized organization is characterized by:","Decision making concentrated at the top",["Wide employee autonomy","No leadership","Team-run decisions"],"Centralization concentrates authority.")
H('247.d.3.I',3,"A group of employees with complementary skills working toward a shared goal is a:","Team",["Crowd","Audience","Customer base"],"Teams share goals.")
H('247.d.3.I',4,"Teamwork is most effective when members:","Share goals and communicate openly",["Work in secret","Compete for credit","Avoid roles"],"Collaboration needs communication.")
H('247.d.3.J',3,"The number of employees a manager directly supervises is the:","Span of control",["Chain of command","Pay grade","Job title"],"Span of control counts direct reports.")
H('247.d.3.J',4,"A manager with a very wide span of control may find it hard to:","Give each employee close attention",["Delegate tasks","Reduce costs","Communicate by email"],"Wide spans reduce supervision time.")
H('247.d.4.A',3,"Hiring based on a candidate's qualifications rather than personal favoritism is:","An ethical HR practice",["Unethical","Illegal in all cases","Unnecessary"],"Ethics in HR means fairness.")
H('247.d.4.A',4,"Keeping employee records private is an example of:","Ethics in human resource management",["A sales tactic","A cost cut","A marketing tool"],"Confidentiality is ethical.")
H('247.d.4.B',3,"A federal law that prohibits employment discrimination on the basis of race, color, religion, sex, or national origin is:","Title VII of the Civil Rights Act",["The Sherman Act","The Tax Code","The Clean Air Act"],"Title VII bars such discrimination.")
