H('247.d.4.C',3,"A hiring practice that seems neutral but disproportionately excludes a protected group has:","Adverse impact",["Positive impact","No effect","Good faith"],"Adverse impact harms a group.")
H('247.d.4.C',4,"Refusing to promote a worker solely because of age is:","Employment discrimination",["Fair practice","A legal rule","A training method"],"Age discrimination is illegal.")
H('247.d.4.D',3,"Repeated unwelcome comments of a sexual nature at work are:","Sexual harassment",["Friendly talk","Teamwork","Training"],"Unwelcome conduct is harassment.")
H('247.d.4.D',4,"An employee who experiences harassment should:","Report it to a supervisor or HR",["Stay silent","Quit immediately without telling","Retaliate"],"Reporting starts correction.")
H('247.d.4.E',3,"Posting a job opening on a company website is a method of:","Recruiting",["Terminating","Training","Auditing"],"Posting attracts applicants.")
H('247.d.4.E',4,"Recruiting from within the company is called:","Internal recruiting",["External recruiting","Outsourcing","Layoff"],"Internal recruiting uses current staff.")
H('247.d.4.F',3,"Reviewing applications, interviewing, and checking references is the:","Selection process",["Termination process","Payroll process","Training process"],"Selection chooses the best candidate.")
H('247.d.4.F',4,"A structured interview asks every candidate:","The same job-related questions",["Random personal questions","Only about hobbies","Different questions"],"Consistency improves fairness.")
H('247.d.4.G',3,"A new employee's first-week orientation is an example of:","Training for newly hired employees",["A layoff","A promotion","An audit"],"Orientation introduces the job.")
H('247.d.4.G',4,"On-the-job training means learning by:","Doing the work with guidance",["Reading only","Watching videos only","Waiting"],"OJT is hands-on.")
H('247.d.4.H',3,"Sending a current employee to a workshop to learn new skills is:","Professional development",["Discipline","A layoff","Recruiting"],"Development builds skills.")
H('247.d.4.H',4,"Professional development benefits a company by:","Improving employee skills and retention",["Lowering morale","Increasing turnover","Reducing quality"],"Growth keeps talent.")
H('247.d.4.I',3,"To attract top workers, a company may offer pay, benefits, and:","Competitive compensation",["Fewer duties","No schedule","Closed doors"],"Compensation must be competitive.")
H('247.d.4.I',4,"Employee compensation includes wages and:","Benefits such as health insurance",["Free parking only","Nothing else","Office supplies"],"Benefits are part of compensation.")
H('247.d.4.J',3,"Reducing the number of employees to cut costs is:","Downsizing",["Expanding","Hiring","Promoting"],"Downsizing reduces headcount.")
H('247.d.4.J',4,"A company might consider downsizing when:","Sales drop sharply and costs must fall",["Profits soar","Demand rises","It is hiring"],"Downsizing responds to weak results.")
H('247.d.4.K',3,"When many employees quit, a company faces high:","Turnover costs",["Profit","Savings","Growth"],"Turnover is expensive.")
H('247.d.4.K',4,"One way to reduce turnover is to:","Improve pay, recognition, and working conditions",["Cut raises","Remove training","Ignore complaints"],"Satisfied employees stay.")
H('247.d.4.L',3,"A workforce with people of different backgrounds can bring:","A wider range of ideas and perspectives",["Fewer skills","Less creativity","Higher conflict only"],"Diversity broadens thinking.")
H('247.d.4.L',4,"A benefit of a diverse workforce is that it:","Reflects and understands diverse customers",["Limits growth","Excludes talent","Reduces ideas"],"Diversity helps serve markets.")
H('247.d.4.M',3,"Researching a company's recent layoffs and how it managed them is:","Studying a contemporary HR case",["Hiring","Training","Advertising"],"Case research builds insight.")
H('247.d.4.M',4,"When researching a diversity case, a student should:","Use credible news and company reports",["Use rumors","Guess","Copy a classmate"],"Reliable sources are key.")
H('247.d.5.A',3,"An inner drive that pushes people to act to reach a goal is:","Motivation",["Fatigue","Confusion","Delay"],"Motivation drives behavior.")
H('247.d.5.A',4,"A manager who understands what drives employees can:","Encourage better performance",["Avoid them","Reduce effort","Lower standards"],"Motivation boosts output.")
H('247.d.5.B',3,"Praise and a sense of achievement from doing a good job are:","Intrinsic rewards",["Extrinsic rewards","Penalties","Taxes"],"Intrinsic rewards come from within.")
H('247.d.5.B',4,"A bonus or a raise is an example of an:","Extrinsic reward",["Intrinsic reward","Warning","Policy"],"Extrinsic rewards are external.")
H('247.d.5.C',3,"An employee feels paid less than a coworker doing the same job. The manager should:","Review the pay fairly and discuss the concern",["Ignore it","Fire the employee","Hide pay data"],"Equity concerns need attention.")
H('247.d.5.C',4,"Perceived inequity can lead employees to:","Lower their effort or leave",["Work harder always","Ignore pay","Increase loyalty"],"Unfairness harms motivation.")
