H('247.d.5.F',3,"Compared with a manager, a leader mainly focuses on:","Inspiring people toward a vision",["Filing forms","Counting inventory","Balancing books"],"Leaders inspire.")
H('247.d.5.F',4,"A manager is typically responsible for:","Planning, organizing, and controlling work",["Only vision","Only motivation","Only charisma"],"Managers keep operations running.")
H('247.d.5.G',3,"A leader who guides a team toward a goal plays the role of:","Direction setter",["Bystander","Critic","Observer only"],"Leaders set direction.")
H('247.d.5.G',4,"One role of a leader is to:","Inspire trust and encourage others",["Hide information","Avoid decisions","Blame the team"],"Trust fuels teams.")
H('247.d.5.H',3,"Honesty, vision, and good communication are traits of an:","Effective leader",["Ineffective leader","Lazy worker","Poor planner"],"Traits support leadership.")
H('247.d.5.H',4,"Which trait helps a leader earn respect?","Integrity",["Secrecy","Favoritism","Inconsistency"],"Integrity builds credibility.")
H('247.d.5.I',3,"A leader who makes all decisions alone uses the:","Autocratic style",["Democratic style","Laissez-faire style","Team style"],"Autocratic leaders decide alone.")
H('247.d.5.I',4,"A leader who asks the team to vote on a decision uses the:","Democratic style",["Autocratic style","Laissez-faire style","Strict style"],"Democratic leaders involve others.")
