H('247.d.5.N',4,"Conversation at lunch about company news is typically:","Informal communication",["Formal communication","A policy","A report"],"Informal communication flows through social ties.")
H('247.d.5.O',3,"A manager holds regular team meetings and invites questions to:","Improve communication",["Waste time","Lower morale","Cut staff"],"Regular exchange helps.")
H('247.d.5.O',4,"To improve communication, a company can:","Encourage open feedback and use clear channels",["Restrict information","Ignore questions","Hide updates"],"Open channels help.")
H('247.d.6.A',3,"Setting standards, measuring performance, and correcting deviations is the:","Control process",["Hiring process","Branding process","Planning process"],"Control compares to standards.")
