H('247.d.6.B',3,"Which is a primary control method?","Budgets",["Gossip","Rumors","Wishes"],"Budgets control spending.")
H('247.d.6.B',4,"Reviewing financial statements to check performance is a form of:","Financial control",["Marketing","Delegation","Branding"],"Financial control monitors money.")
