H('247.d.6.D',4,"Management information systems are strategically important because they:","Supply timely data for decisions",["Replace employees","Add confusion","Slow reports"],"Timely data guides strategy.")
H('247.d.6.E',3,"When departments share sales data, the company can:","Coordinate better",["Duplicate work","Lose accuracy","Delay orders"],"Sharing aligns work.")
H('247.d.6.E',4,"Gathering information is not useful unless it is:","Shared with people who can act on it",["Locked away","Outdated","Incomplete"],"Information must reach users.")
