H('247.d.6.M',3,"Researching a past Deming winner requires:","Appropriate criteria and credible sources",["Rumors","Guesses","No sources"],"Reliable research is essential.")
H('247.d.6.M',4,"When critiquing a Deming recipient, compare its practices to:","The award's quality standards",["A competitor's ads","A movie","A rumor"],"Use the stated standards.")
