H('247.d.7.E',3,"Job shadowing a manager is a:","Career development activity",["Disciplinary action","Layoff","Payroll task"],"Shadowing explores careers.")
H('247.d.7.E',4,"A career development activity that builds skills for advancement is:","Attending a management workshop",["Ignoring feedback","Avoiding training","Skipping class"],"Workshops build skills.")
