H('247.d.7.G',3,"Arriving on time, being honest, and showing initiative help foster:","Career advancement",["Layoffs","Conflicts","Delays"],"Good traits help promotion.")
H('247.d.7.G',4,"Which trait most helps an employee earn a promotion?","Dependability",["Lateness","Gossip","Carelessness"],"Dependability gains trust.")
H('247.d.8.A',3,"Listing the people, money, and equipment a project needs is part of:","Initiating a project",["Closing a project","Monitoring only","Marketing"],"Initiation identifies resources.")
H('247.d.8.A',4,"Before a project starts, a manager should identify:","The resources needed and the project's purpose",["The final results","The next project","The retirement plan"],"Initiation defines scope.")
H('247.d.8.B',3,"A written project plan lists tasks, deadlines, and:","Responsible people",["Rumors","Songs","Menus"],"Plans assign ownership.")
H('247.d.8.B',4,"A project plan helps a team by:","Showing who does what and by when",["Hiding tasks","Removing deadlines","Avoiding roles"],"Clarity aids execution.")
